<script setup lang="ts">import{Head,router}from'@inertiajs/vue3';import AdvertiserPortalHeader from '@/components/Advertiser/AdvertiserPortalHeader.vue';import{Button}from'@/components/ui/button';const props=defineProps<{advertiser:any;membership:any;invoice:any}>();const money=(v:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:props.invoice.currency||'USD'}).format((v||0)/100);</script><template><Head :title="invoice.invoice_number"/><div class="space-y-6 p-6"><AdvertiserPortalHeader :title="invoice.invoice_number" :description="`${invoice.status} · ${invoice.campaign?.name||'Advertising sponsorship'}`" :advertiser="advertiser"><template #actions><Button v-if="invoice.balance_cents>0&&!['void','refunded'].includes(invoice.status)" @click="router.post(`/advertiser/invoices/${invoice.id}/checkout`)">Pay {{money(invoice.balance_cents)}}</Button></template></AdvertiserPortalHeader><div class="grid gap-4 md:grid-cols-4"><div class="rounded-xl border p-4"><p class="text-sm text-muted-foreground">Total</p><p class="text-xl font-semibold">{{money(invoice.total_cents)}}</p></div><div class="rounded-xl border p-4"><p class="text-sm text-muted-foreground">Paid</p><p class="text-xl font-semibold">{{money(invoice.paid_cents)}}</p></div><div class="rounded-xl border p-4"><p class="text-sm text-muted-foreground">Refunded</p><p class="text-xl font-semibold">{{money(invoice.refunded_cents)}}</p></div><div class="rounded-xl border p-4"><p class="text-sm text-muted-foreground">Balance</p><p class="text-xl font-semibold">{{money(invoice.balance_cents)}}</p></div></div><section class="rounded-xl border p-5"><h2 class="font-semibold">Line items</h2><div class="mt-4 divide-y"><div v-for="x in invoice.items" class="flex justify-between py-3"><div><p class="font-medium">{{x.description}}</p><p class="text-sm text-muted-foreground">{{x.quantity}} × {{money(x.unit_price_cents)}}</p></div><strong>{{money(x.total_cents)}}</strong></div></div></section><section class="rounded-xl border p-5"><h2 class="font-semibold">Payment history</h2><div class="mt-4 divide-y"><div v-for="p in invoice.payments" class="flex justify-between py-3"><div><p class="font-medium">{{p.type}} · {{p.provider}}</p><p class="text-sm text-muted-foreground">{{p.status}} · {{p.processed_at||p.created_at}}</p></div><strong>{{money(p.amount_cents)}}</strong></div><p v-if="!invoice.payments.length" class="py-5 text-sm text-muted-foreground">No payment activity.</p></div></section></div></template>
